/**
 ******************************************************************************
 * @file    battery_monitor.c
 * TEAM CODE (owner: Brendon - battery monitor and USB-C MSC) - written by the BJT2 team, not generated by STM32CubeMX.
 * @brief   1 Hz battery snapshot service — hardware-independent PD5b refactor.
 *
 * Owner: Brendon Bone. Poll logic ported from brendon_battery_usb.c
 * (background_poll_snapshot / Brendon_Task), with the tick injected instead
 * of HAL_GetTick and plausibility checks added on top of the raw reads.
 * The rules are described in battery_monitor.h.
 *
 * No task of its own: BatMon_Init runs once in Brendon_Init (before the
 * kernel starts), then BrendonTask calls BatMon_Tick on every loop pass.
 *
 * One poll (batmon_poll), step by step:
 *   1. the five core reads: Voltage, AverageCurrent, SOC, RemainingCapacity,
 *      FullChargeCapacity; any failure makes the poll invalid
 *   2. only if all five worked: Current() and the gauge's two time estimates
 *   3. an active debug SOC override replaces the SOC
 *   4. valid and plausible -> new snapshot, then the alarm / lockout latches
 *      (batmon_update_alarms); otherwise .valid = 0 and the latches stay
 * Generative AI was used to assist in the refactoring process.
 ******************************************************************************
 */
#include "battery_monitor.h"
#include "bq34z100.h"

#include <stddef.h>

/**
 * @brief Range-check a raw poll before publishing it.
 *
 * The gauge can NACK mid-read or return garbage during brown-out; a snapshot
 * is only published as valid when the values are physically plausible.
 *
 * @return 1 when plausible, 0 when the reading should be rejected.
 */
static uint8_t batmon_plausible(uint16_t voltage_mV, uint8_t soc_pct)
{
    if (soc_pct > 100U) {
        return 0U;
    }
    if (voltage_mV < BATMON_VOLTAGE_MIN_MV || voltage_mV > BATMON_VOLTAGE_MAX_MV) {
        return 0U;
    }
    return 1U;
}

/**
 * @brief Apply the hysteresis rules to the alarm latches for one valid SOC.
 *
 * Comparator-with-hysteresis (Schmitt-trigger) behaviour: assert strictly
 * below the alarm threshold, release only at/above the higher clear
 * threshold, hold the previous state inside the dead band. The speaker
 * lockout follows the critical latch on the way down but only releases at
 * BATMON_LOCKOUT_CLEAR_SOC_PCT. Called ONLY for valid polls — a
 * failed/implausible poll must leave every latch untouched.
 *
 * Example, SOC readings 31, 29, 30, 31, 29, 32 %: the low latch sets at 29,
 * holds through 30 and 31, and clears at 32, so it rises once (one LOW beep
 * in brendon_battery_usb.c). A plain "below 30 %" test would rise at both
 * 29s and beep twice.
 */
static void batmon_update_alarms(Battery_Monitor *mon, uint8_t soc)
{
    if (soc < BATMON_LOW_SOC_PCT) {
        mon->low_latched = 1U;
    } else if (soc >= BATMON_LOW_CLEAR_SOC_PCT) {
        mon->low_latched = 0U;
    }
    /* 30-31%: dead band — low latch holds. */

    if (soc < BATMON_CRITICAL_SOC_PCT) {
        mon->crit_latched = 1U;
    } else if (soc >= BATMON_CRITICAL_CLEAR_SOC_PCT) {
        mon->crit_latched = 0U;
    }
    /* 10-11%: dead band — critical latch holds. */

    /* Speaker lockout: a separate latch. It sets whenever the critical latch
     * is set, so the two always engage together. */
    if (mon->crit_latched == 1U) {
        mon->lockout_latched = 1U;
    } else if (soc >= BATMON_LOCKOUT_CLEAR_SOC_PCT) {
        mon->lockout_latched = 0U;
    }
    /* 12-31% after a critical: the critical alarm has released but the
     * lockout holds until the battery is back at the low alarm's clear level. */
}

/**
 * @brief Take one battery reading and publish it into the snapshot.
 *
 * Marks the snapshot valid only if EVERY core read succeeded and the values
 * pass the plausibility check, so a failed or absent gauge reads as stale
 * rather than a false alarm. The instant current and the two time estimates
 * are read after the core reads and never affect validity (see the header).
 */
static void batmon_poll(Battery_Monitor *mon)
{
    uint16_t v = 0U, rem = 0U, fcc = 0U;
    uint16_t tte = BATMON_TIME_UNKNOWN, ttf = BATMON_TIME_UNKNOWN;
    int16_t  i = 0, i_now = 0;
    uint8_t  soc = 0U;
    uint8_t  ok = 1U, now_ok = 0U;

    if (BQ34Z100_ReadVoltage_mV(mon->bus, &v) != BQ_OK)              { ok = 0U; }
    if (BQ34Z100_ReadAverageCurrent_mA(mon->bus, &i) != BQ_OK)       { ok = 0U; }
    if (BQ34Z100_ReadSOC_pct(mon->bus, &soc) != BQ_OK)               { ok = 0U; }
    if (BQ34Z100_ReadRemainingCapacity_mAh(mon->bus, &rem) != BQ_OK) { ok = 0U; }
    if (BQ34Z100_ReadFullChargeCapacity_mAh(mon->bus, &fcc) != BQ_OK){ ok = 0U; }

    /* The extras, only once the gauge has answered all five core reads
     * (otherwise each would only add another bus timeout). None of them can
     * make the poll bad:
     *  - Current(), the instant current for battery_time.c's 2-minute average.
     *    If it fails, AverageCurrent stands in: a slower figure, but still a
     *    measured current, and one failed read must not blank the times.
     *    now_ok = 0 marks it, so the average leaves it out (AverageCurrent
     *    still carries the old current for minutes after a charger change).
     *  - the gauge's own time estimates (debug screen): a failed read is
     *    "no estimate". */
    if (ok == 1U) {
        if (BQ34Z100_ReadInstantCurrent_mA(mon->bus, &i_now) == BQ_OK)    { now_ok = 1U; }
        else                                                              { i_now = i; }
        if (BQ34Z100_ReadAverageTimeToEmpty_min(mon->bus, &tte) != BQ_OK) { tte = BATMON_TIME_UNKNOWN; }
        if (BQ34Z100_ReadAverageTimeToFull_min(mon->bus, &ttf) != BQ_OK)  { ttf = BATMON_TIME_UNKNOWN; }
    }

    /* Debug SOC override: the gauge's SOC was still read above (a gauge that
     * stops answering still makes the poll invalid), but from here on the
     * injected value stands in for it: plausibility check, snapshot and every
     * latch. Voltage, current and the times stay the gauge's. */
    if (mon->soc_override == 1U) {
        soc = mon->soc_override_pct;
    }

    if (ok == 1U && batmon_plausible(v, soc) == 1U) {
        mon->snap.voltage_mV        = v;
        mon->snap.current_mA        = i;
        mon->snap.current_now_mA    = i_now;
        mon->snap.current_now_ok    = now_ok;
        mon->snap.soc_pct           = soc;
        mon->snap.remaining_mAh     = rem;
        mon->snap.full_capacity_mAh = fcc;
        mon->snap.tte_min           = tte;
        mon->snap.ttf_min           = ttf;
        mon->snap.valid             = 1U;
        batmon_update_alarms(mon, soc);
    } else {
        mon->snap.valid   = 0U;   /* latches deliberately untouched */
        /* No time estimate and no instant current from a bad reading: the
         * screen shows --:-- rather than an old time next to "No gauge". */
        mon->snap.current_now_mA = 0;
        mon->snap.current_now_ok = 0U;
        mon->snap.tte_min = BATMON_TIME_UNKNOWN;
        mon->snap.ttf_min = BATMON_TIME_UNKNOWN;
    }
}

/**
 * @brief Initialise the monitor, probe the gauge, take the first snapshot.
 */
BatMon_Status BatMon_Init(Battery_Monitor *mon, const BQ_Bus *bus)
{
    if (mon == NULL || bus == NULL ||
        bus->mem_read == NULL || bus->is_ready == NULL) {
        return BATMON_BAD_PARAM;
    }

    mon->bus              = bus;
    mon->snap.voltage_mV        = 0U;
    mon->snap.current_mA        = 0;
    mon->snap.current_now_mA    = 0;
    mon->snap.current_now_ok    = 0U;
    mon->snap.soc_pct           = 0U;
    mon->snap.remaining_mAh     = 0U;
    mon->snap.full_capacity_mAh = 0U;
    mon->snap.valid             = 0U;
    mon->snap.tte_min           = BATMON_TIME_UNKNOWN;
    mon->snap.ttf_min           = BATMON_TIME_UNKNOWN;
    mon->last_poll_ms     = 0U;
    mon->poll_started     = 0U;
    mon->gauge_present    = 0U;
    mon->low_latched      = 0U;
    mon->crit_latched     = 0U;
    mon->lockout_latched  = 0U;
    mon->poll_now         = 0U;
    mon->soc_override     = 0U;
    mon->soc_override_pct = 0U;
    mon->soc_override_until_ms = 0U;

    if (BQ34Z100_Init(bus) == BQ_OK) {
        mon->gauge_present = 1U;
        batmon_poll(mon);       /* consumers get data straight away */
        mon->poll_started = 1U; /* next background poll once 1 s has elapsed */
        return BATMON_OK;
    }

    return BATMON_NO_GAUGE;
}

/**
 * @brief Re-probe a gauge that was absent at init.
 */
BatMon_Status BatMon_RetryProbe(Battery_Monitor *mon)
{
    if (mon == NULL || mon->bus == NULL) {
        return BATMON_BAD_PARAM;
    }

    if (mon->gauge_present == 1U) {
        return BATMON_OK;   /* nothing to do */
    }

    if (BQ34Z100_Init(mon->bus) != BQ_OK) {
        return BATMON_NO_GAUGE;
    }

    mon->gauge_present = 1U;
    batmon_poll(mon);
    mon->poll_started = 1U;
    return BATMON_OK;
}

/**
 * @brief Cooperative tick — polls once per BATMON_POLL_INTERVAL_MS, or at
 *        once when a debug SOC override was set, cleared or has just ended.
 *
 * Unsigned subtraction keeps the elapsed calculation correct across the
 * 32-bit tick wrap (~49.7 days).
 */
uint8_t BatMon_Tick(Battery_Monitor *mon, uint32_t now_ms)
{
    if (mon == NULL || mon->gauge_present == 0U) {
        return 0U;
    }

    /* The override ends by itself. Signed difference = "now has reached the
     * end time", correct across the tick wrap for anything shorter than
     * ~24 days (the longest override, 65535 s, is ~18 h). Poll at once so
     * the real SOC is back without waiting for the next second. */
    if (mon->soc_override == 1U &&
        (int32_t)(now_ms - mon->soc_override_until_ms) >= 0) {
        mon->soc_override = 0U;
        mon->poll_now     = 1U;
    }

    if (mon->poll_started == 1U && mon->poll_now == 0U &&
        (uint32_t)(now_ms - mon->last_poll_ms) < BATMON_POLL_INTERVAL_MS) {
        return 0U;
    }

    batmon_poll(mon);
    mon->last_poll_ms = now_ms;
    mon->poll_started = 1U;
    mon->poll_now     = 0U;
    return 1U;
}

/**
 * @brief Copy the latest cached snapshot to the caller (no bus traffic).
 */
void BatMon_GetSnapshot(const Battery_Monitor *mon, Battery_Snapshot_t *out)
{
    if (out == NULL) {
        return;
    }

    if (mon == NULL) {
        out->valid   = 0U;
        /* Like every invalid snapshot: no time estimate and no instant
         * current, never whatever the caller's buffer held (the Battery
         * screen would show it as a time). */
        out->current_now_mA = 0;
        out->current_now_ok = 0U;
        out->tte_min = BATMON_TIME_UNKNOWN;
        out->ttf_min = BATMON_TIME_UNKNOWN;
        return;
    }

    *out = mon->snap;
}

/**
 * @brief 1 while the low alarm is latched (asserts < 30%, releases >= 32%)
 *        and the snapshot is valid — never reports on stale data.
 */
uint8_t BatMon_IsLowBattery(const Battery_Monitor *mon)
{
    if (mon == NULL) {
        return 0U;
    }
    return (mon->snap.valid == 1U && mon->low_latched == 1U) ? 1U : 0U;
}

/**
 * @brief 1 while the critical alarm is latched (asserts < 10%, releases
 *        >= 12%) and the snapshot is valid — never reports on stale data.
 *        The speaker mute itself is BatMon_IsSpeakerLockout.
 */
uint8_t BatMon_IsCriticalBattery(const Battery_Monitor *mon)
{
    if (mon == NULL) {
        return 0U;
    }
    return (mon->snap.valid == 1U && mon->crit_latched == 1U) ? 1U : 0U;
}

/**
 * @brief 1 while the speaker lockout is latched (sets < 10%, releases >= 32%).
 *
 * Not gated by .valid on purpose: an invalid snapshot means "no new
 * information", and no new information must not switch the speaker back on.
 * The latch only ever moves on valid polls (batmon_update_alarms).
 */
uint8_t BatMon_IsSpeakerLockout(const Battery_Monitor *mon)
{
    if (mon == NULL) {
        return 0U;
    }
    return (mon->lockout_latched == 1U) ? 1U : 0U;
}

/**
 * @brief 1 if the gauge has ACKed its address at init or a later retry.
 */
uint8_t BatMon_GaugePresent(const Battery_Monitor *mon)
{
    return (mon != NULL && mon->gauge_present == 1U) ? 1U : 0U;
}

/**
 * @brief Start (seconds > 0) or clear (seconds == 0) the debug SOC override.
 *
 * Refused without a gauge: there is no reading to override, and an override
 * stored now would suddenly apply when a late gauge is found. Clearing ignores
 * soc_pct, so a clear can never be refused for a bad value.
 */
BatMon_Status BatMon_SetSocOverride(Battery_Monitor *mon, uint8_t soc_pct,
                                    uint16_t seconds, uint32_t now_ms)
{
    if (mon == NULL || (seconds > 0U && soc_pct > 100U)) {
        return BATMON_BAD_PARAM;
    }
    if (mon->gauge_present == 0U) {
        return BATMON_NO_GAUGE;
    }

    if (seconds == 0U) {
        mon->soc_override = 0U;
    } else {
        mon->soc_override          = 1U;
        mon->soc_override_pct      = soc_pct;
        mon->soc_override_until_ms = now_ms + (uint32_t)seconds * 1000U;
    }
    mon->poll_now = 1U;     /* show the change at the next tick, not up to 1 s later */
    return BATMON_OK;
}

/**
 * @brief 1 while a debug SOC override is active.
 */
uint8_t BatMon_SocOverrideActive(const Battery_Monitor *mon)
{
    return (mon != NULL && mon->soc_override == 1U) ? 1U : 0U;
}

/**
 * @brief Seconds the override still runs, rounded up so the count reaches 0
 *        exactly when the override ends.
 */
uint16_t BatMon_SocOverrideSecondsLeft(const Battery_Monitor *mon, uint32_t now_ms)
{
    int32_t  left_ms;
    uint32_t left_s;

    if (mon == NULL || mon->soc_override == 0U) {
        return 0U;
    }
    left_ms = (int32_t)(mon->soc_override_until_ms - now_ms);   /* wrap-safe, like BatMon_Tick */
    if (left_ms <= 0) {
        return 0U;          /* time is up: the next BatMon_Tick ends it */
    }
    left_s = ((uint32_t)left_ms + 999U) / 1000U;
    return (left_s > 0xFFFFU) ? 0xFFFFU : (uint16_t)left_s;
}
